"use client"

import { useEffect, useState } from "react"

const CLOUD_TRAIN_HTML_BASE64 = ""

function decodeBase64Utf8(value: string) {
  const binary = window.atob(value)
  const bytes = new Uint8Array(binary.length)
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i)
  return new TextDecoder("utf-8").decode(bytes)
}

export default function CloudTrainTool() {
  const [srcDoc, setSrcDoc] = useState("")

  useEffect(() => {
    setSrcDoc(decodeBase64Utf8(CLOUD_TRAIN_HTML_BASE64))
  }, [])

  return (
    <main className="fixed inset-0 overflow-hidden bg-[#05090c]">
      {srcDoc ? (
        <iframe
          title="云间列车 · Cloud Train"
          srcDoc={srcDoc}
          className="h-full w-full border-0"
          sandbox="allow-scripts allow-same-origin"
          allow="clipboard-write; eye-dropper"
        />
      ) : (
        <div className="grid h-full place-items-center bg-[#05090c] text-xs tracking-[0.18em] text-white/35">
          CLOUD TRAIN
        </div>
      )}
    </main>
  )
}
